rule.example:

// panics if x is not an int
n := x.(int)

// safe — check ok
n, ok := x.(int)
if !ok {
    return errors.New("not an int")
}


// identical if/else — flag
if cond {
    doX()
    doY()
} else {
    doX()
    doY()
}

// identical switch cases — flag
switch x {
case 1:
    handle()
case 2:
    handle()
}


type A struct {}
type B struct { A }
type C struct { B }
type D struct { C }
type E struct { D } // depth 4 — flag
